  @type t :: %__MODULE__{
          api_key: String.t(),
          store: String.t(),
          base_url: String.t(),
          timeout: non_neg_integer(),
          max_retries: non_neg_integer(),
          req_options: keyword(),
          lifecycle_hook: (map() -> any()) | nil
        }
  defstruct [
    :api_key,
    :access_token,
    :customer_session,
    :browser_session,
    :client_id,
    :client_secret,
    :store,
    :lifecycle_hook,
    base_url: @default_base_url,
    timeout: @default_timeout,
    max_retries: @default_max_retries,
    req_options: []
  ]

  @spec new(keyword()) :: t()
  def new(opts \\ []) do
    %__MODULE__{
      api_key: Keyword.get(opts, :api_key) || System.get_env("SELLAPP_API_KEY"),
      access_token: Keyword.get(opts, :access_token),
      customer_session: Keyword.get(opts, :customer_session),
      browser_session: Keyword.get(opts, :browser_session),
      client_id: Keyword.get(opts, :client_id),
      client_secret: Keyword.get(opts, :client_secret),
      store: Keyword.get(opts, :store) || System.get_env("SELLAPP_STORE"),
      base_url: Keyword.get(opts, :base_url, @default_base_url),
      timeout: Keyword.get(opts, :timeout, @default_timeout),
      max_retries: Keyword.get(opts, :max_retries, @default_max_retries),
      req_options: Keyword.get(opts, :req_options, []),
      lifecycle_hook: Keyword.get(opts, :lifecycle_hook)
    }
    |> validate_configuration!()
  end

  @spec request(t(), atom(), String.t(), map(), keyword()) ::
          {:ok, term()} | {:error, Error.error()}
  def request(client, method, path, params \\ %{}, opts \\ []) do
    with {:ok, auth_headers} <- credentials(client, method, path, opts),
         {:ok, path} <- validate_path(path) do
      do_request(
        client,
        method,
        path,
        params,
        prepare_options(Keyword.put(opts, :auth_headers, auth_headers)),
        0
      )
    end
  end

  @doc "Makes a custom relative API request without generated schema guarantees."
  def custom_request(client, method, path, opts \\ []) do
    query = Keyword.get(opts, :query, %{})
    body = Keyword.get(opts, :body)
    params = if is_nil(body), do: query, else: body

    request(
      client,
      method,
      path,
      params,
      opts
      |> Keyword.put(:request_body, not is_nil(body))
      |> Keyword.put(:extra_query, query)
      |> Keyword.put(:idempotency_supported, false)
    )
  end

  def build_url(client, path, params) do
    query = URI.encode_query(params)
    base = String.trim_trailing(client.base_url, "/") <> path
    if query == "", do: base, else: base <> "?" <> query
  end

  def merge_defaults(params, defaults), do: Map.merge(params, defaults)

  def put_inferred(params, key, value),
    do: if(Map.has_key?(params, key), do: params, else: Map.put(params, key, value))

  defp contract(method, path) do
    Enum.find(@contracts, fn c ->
      c["method"] == to_string(method) and
        length(String.split(c["path"], "/")) == length(String.split(path, "/")) and
        Enum.zip(String.split(c["path"], "/"), String.split(path, "/"))
        |> Enum.all?(fn {a, b} -> a == b or String.starts_with?(a, "{") end)
    end) || %{"auth" => %{"apiKey" => true, "apiKeyRequiresStore" => true}, "retry" => %{}}
  end

  defp present(value), do: is_binary(value) and byte_size(value) > 0

  defp credentials(client, method, path, opts) do
    auth = contract(method, path)["auth"]
    session = Keyword.get(opts, :customer_session, client.customer_session)

    cond do
      auth["customerSession"] && present(session) ->
        {:ok, [{"authorization", "Bearer " <> session}]}

      auth["accessToken"] && present(client.access_token) ->
        bearer_headers(
          client.access_token,
          if(auth["accessTokenRequiresStore"], do: client.store, else: nil),
          auth["accessTokenRequiresStore"]
        )

      auth["apiKey"] && present(client.api_key) ->
        bearer_headers(
          client.api_key,
          if(Map.get(auth, "apiKeyUsesStore", true), do: client.store, else: nil),
          auth["apiKeyRequiresStore"]
        )

      auth["browserSession"] && present(client.browser_session) ->
        {:ok, [{"cookie", client.browser_session}]}

      auth["clientBasic"] && present(client.client_id) ->
        {:ok,
         [
           {"authorization",
            "Basic " <>
              Base.encode64(
                URI.encode_www_form(client.client_id) <>
                  ":" <> URI.encode_www_form(client.client_secret || "")
              )}
         ]}

      auth["anonymous"] ->
        {:ok, []}

      true ->
        {:error,
         %Error.Configuration{message: "credentials required by this operation are missing"}}
    end
  end

  defp bearer_headers(token, store, required) do
    if required && not present(store),
      do: {:error, %Error.Configuration{message: "store is required for this credential"}},
      else:
        {:ok,
         [{"authorization", "Bearer " <> token}] ++
           if(present(store), do: [{"x-store", store}], else: [])}
  end

  defp validate_configuration!(client) do
    unless is_integer(client.timeout) and client.timeout > 0,
      do: raise(ArgumentError, "timeout must be a positive integer")

    unless is_integer(client.max_retries) and client.max_retries >= 0,
      do: raise(ArgumentError, "max_retries must be a non-negative integer")

    client
  end

  defp validate_path(path) when is_binary(path) do
    uri = URI.parse(path)

    if uri.scheme || uri.host || uri.userinfo || uri.fragment ||
         not String.starts_with?(path, "/"),
       do:
         {:error,
          %Error.Configuration{
            message: "request path must be relative, absolute-path form, and contain no fragment"
          }},
       else: {:ok, path}
  end

  defp validate_path(_),
    do: {:error, %Error.Configuration{message: "request path must be a string"}}

  defp prepare_options(opts) do
    retries = Keyword.get(opts, :max_retries)
    timeout = Keyword.get(opts, :timeout)

    if retries != nil and (not is_integer(retries) or retries < 0),
      do: raise(ArgumentError, "max_retries must be a non-negative integer")

    if timeout != nil and (not is_integer(timeout) or timeout <= 0),
      do: raise(ArgumentError, "timeout must be a positive integer")

    key = Keyword.get(opts, :idempotency_key)

    if key != nil and not is_binary(key),
      do: raise(ArgumentError, "idempotency_key must be a string")

    opts
  end

  defp do_request(client, method, path, params, opts, attempt) do
    retries = Keyword.get(opts, :max_retries, client.max_retries)
    timeout = Keyword.get(opts, :timeout, client.timeout)
    contract = contract(method, path)
    base_url = Keyword.get(opts, :base_url, client.base_url)

    base_url =
      if contract["server"],
        do:
          if(base_url == @default_base_url,
            do: contract["server"],
            else: URI.to_string(%{URI.parse(base_url) | path: nil, query: nil, fragment: nil})
          ),
        else: base_url

    headers = request_headers(client, opts)

    request =
      client.req_options ++
        [
          method: method,
          url: String.trim_trailing(base_url, "/") <> path,
          headers: headers,
          receive_timeout: timeout,
          retry: false,
          redirect: false
        ]

    query_only = method in [:get, :delete, :head] and not Keyword.get(opts, :request_body, false)
    query = Map.merge(if(query_only, do: params, else: %{}), Keyword.get(opts, :extra_query, %{}))
    body = if(query_only, do: nil, else: Map.merge(params, Keyword.get(opts, :extra_body, %{})))

    request =
      cond do
        contract["form"] && present(client.client_id) &&
            (Map.has_key?(body || %{}, "client_id") || Map.has_key?(body || %{}, "client_secret")) ->
          raise ArgumentError, "use Basic or body credentials, never both"

        contract["form"] ->
          Keyword.put(request, :form, form_fields(body || %{}))

        query_only ->
          Keyword.put(request, :params, encode_query_params(query))

        Keyword.get(opts, :body_encoding) == :multipart ->
          Keyword.put(request, :form_multipart, multipart_fields(body))

        true ->
          Keyword.put(request, :json, body)
      end

    started = System.monotonic_time(:millisecond)
    retry_safe = contract["retry"]["never"] != true && retry_safe?(method, opts)

    emit_hook(client, opts, %{
      phase: :start,
      operation_id: Keyword.get(opts, :operation_id),
      attempt: attempt + 1
    })

    case Req.request(request) do
      {:ok, %Req.Response{status: status} = response}
