          phase: :retry,
          outcome: :retry,
          operation_id: Keyword.get(opts, :operation_id),
          attempt: attempt + 1,
          duration_ms: System.monotonic_time(:millisecond) - started,
          status: status,
          request_id: header(response.headers, "x-request-id")
        })

        retry_wait(response, attempt)
        do_request(client, method, path, params, opts, attempt + 1)

      {:ok, %Req.Response{status: status, body: body, headers: response_headers}}
      when status >= 200 and status < 400 ->
        request_id = header(response_headers, "x-request-id")

        emit_hook(client, opts, %{
          phase: :finish,
          outcome: :success,
          operation_id: Keyword.get(opts, :operation_id),
          attempt: attempt + 1,
          duration_ms: System.monotonic_time(:millisecond) - started,
          status: status,
          request_id: request_id
        })

        value =
          if Keyword.get(opts, :with_response, false),
            do: %SellApp.Response{
              data: body,
              status: status,
              headers: response_headers,
              request_id: request_id
            },
            else: body

        {:ok, value}

      {:ok, %Req.Response{status: status, body: body, headers: response_headers}} ->
        error =
          if status == 401,
            do: Error.Authentication.from_response(status, body, response_headers),
            else: Error.Api.from_response(status, body, response_headers)

        emit_hook(client, opts, %{
          phase: :error,
          outcome: :api_error,
          operation_id: Keyword.get(opts, :operation_id),
          attempt: attempt + 1,
          duration_ms: System.monotonic_time(:millisecond) - started,
          status: status,
          request_id: error.request_id
        })

        {:error, error}

      {:error, _exception} when attempt < retries and retry_safe ->
        emit_hook(client, opts, %{
          phase: :retry,
          outcome: :retry,
          operation_id: Keyword.get(opts, :operation_id),
          attempt: attempt + 1,
          duration_ms: System.monotonic_time(:millisecond) - started,
          status: nil,
          request_id: nil
        })

        retry_wait(nil, attempt)
        do_request(client, method, path, params, opts, attempt + 1)

      {:error, %Req.TransportError{reason: :timeout} = exception} ->
        emit_hook(client, opts, %{
          phase: :error,
          outcome: :timeout,
          operation_id: Keyword.get(opts, :operation_id),
          attempt: attempt + 1,
          duration_ms: System.monotonic_time(:millisecond) - started,
          status: nil,
          request_id: nil
        })

        {:error, %Error.Timeout{message: Exception.message(exception)}}

      {:error, exception} ->
        emit_hook(client, opts, %{
          phase: :error,
          outcome: :transport_error,
          operation_id: Keyword.get(opts, :operation_id),
          attempt: attempt + 1,
          duration_ms: System.monotonic_time(:millisecond) - started,
          status: nil,
          request_id: nil
        })

        {:error, %Error.Transport{message: Exception.message(exception), reason: exception}}
    end
  rescue
    exception in [Jason.DecodeError, Protocol.UndefinedError] ->
      emit_hook(client, opts, %{
        phase: :error,
        outcome: :serialization_error,
        operation_id: Keyword.get(opts, :operation_id),
        attempt: attempt + 1,
        status: nil,
        request_id: nil
      })

      {:error, %Error.Serialization{message: Exception.message(exception)}}
  end

  defp retry_safe?(method, opts) do
    key = Keyword.get(opts, :idempotency_key)

    method in [:get, :head, :options, :put, :delete] or
      (Keyword.get(opts, :idempotency_supported, false) and is_binary(key) and
         byte_size(String.trim(key)) > 0)
  end

  defp request_headers(_client, opts) do
    idempotency = Keyword.get(opts, :idempotency_key)
    base = Keyword.fetch!(opts, :auth_headers) ++ [{"user-agent", "SellApp Elixir/0.1.1"}]

    base =
      if is_binary(idempotency) and String.trim(idempotency) != "",
        do: [{"idempotency-key", idempotency} | base],
        else: base

    Enum.reject(Keyword.get(opts, :headers, []), fn {key, _} ->
      String.downcase(to_string(key)) in ["authorization", "x-store", "cookie"]
    end) ++ base
  end

  defp form_fields(params) do
    Enum.flat_map(params, fn
      {_key, nil} ->
        []

      {key, values} when is_list(values) ->
        Enum.map(values, &{to_string(key) <> "[]", to_string(&1)})

      {key, value} ->
        [{to_string(key), to_string(value)}]
    end)
  end

  defp encode_query_params(params) do
    Map.new(params, fn
      {key, value} when is_list(value) -> {key, Enum.join(value, ",")}
      {key, value} when is_map(value) -> {key, Jason.encode!(value)}
      pair -> pair
    end)
  end

  defp multipart_fields(body) do
    Enum.map(body, fn
      {key, {:file, path}} -> {to_string(key), {:file, path}}
      {key, value} when is_binary(value) -> {to_string(key), value}
      {key, value} -> {to_string(key), Jason.encode!(value)}
    end)
  end

  defp retry_wait(response, attempt) do
    delay =
      retry_after_ms(response) ||
        min(round(250 * :math.pow(2, attempt) * (1 + :rand.uniform() * 0.25)), 30_000)

    Process.sleep(min(max(delay, 0), 30_000))
  end

  defp retry_after_ms(nil), do: nil

  defp retry_after_ms(response) do
    case header(response.headers, "retry-after") do
      nil ->
        nil

      value ->
        case Integer.parse(value) do
          {seconds, ""} when seconds >= 0 -> seconds * 1_000
          _ -> http_date_delay(value)
        end
    end
  end

  defp http_date_delay(value) do
    date = :httpd_util.convert_request_date(String.to_charlist(value))

    if is_tuple(date),
      do:
        max(
          (:calendar.datetime_to_gregorian_seconds(date) -
             :calendar.datetime_to_gregorian_seconds(:calendar.universal_time())) * 1_000,
          0
        ),
      else: nil
  rescue
    _ -> nil
  end

  defp header(headers, name) do
    case Enum.find(headers, fn {key, _} -> String.downcase(to_string(key)) == name end) do
      {_, [value | _]} -> value
      {_, value} when is_binary(value) -> value
      _ -> nil
    end
  end

  defp emit_hook(client, opts, event) do
    hook = Keyword.get(opts, :lifecycle_hook, client.lifecycle_hook)
    if is_function(hook, 1), do: hook.(event)
    :ok
  end
end
